#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include "doctest.h"
#include "eniesLobby.h"
#include <fstream>
#include <string>   

using namespace std;

struct ExactCaseData { const char* input; const char* expected; };

static string runExactCase(int index, const char* input) {
    string filename = "exact_12000_case_" + to_string(index) + ".txt";
    ofstream fout(filename.c_str());
    fout << input;
    fout.close();
    EniesLobbyBattle battle(filename);
    battle.runBattle();
    string result = battle.getResult();
    remove(filename.c_str());
    return result;
}

